import csv,json,io
from pathlib import Path
checks=[]
for j in [0,1]:
 r=json.loads(Path(f'export-fixture{j}.json').read_text());rows=list(csv.DictReader(io.StringIO(Path(f'export-fixture{j}.csv').read_text())));assert len(rows)==r['total'];assert [x['id'] for x in rows]==[x['id'] for x in r['originalInput']['cards']];assert sum(int(x['minutes']) for x in rows)==r['summary']['minutes'];md=Path(f'export-fixture{j}.md').read_text();assert all(c['text'] in md for c in r['agenda']);assert [c['position'] for c in r['agenda']]==list(range(1,r['total']+1));matrix=[x['similarities'] for x in r['reviews']];ids=[x['id'] for x in r['originalInput']['cards']];ix=[ids.index(x['id']) for x in r['agenda']];assert abs(sum(matrix[k][k+1] for k in range(len(ids)-1))-r['summary']['baselineScore'])<1e-10;assert abs(sum(matrix[a][b] for a,b in zip(ix,ix[1:]))-r['summary']['reviewedScore'])<1e-10;checks.append(f'fixture {j}: all IDs/text/durations, contiguous offsets and Markdown agenda preserved')
r=json.loads(Path('export-reviewed.json').read_text());rows=list(csv.DictReader(io.StringIO(Path('export-reviewed.csv').read_text())));assert rows[0]['review_note']=="'"+r['reviews'][0]['reviewNote'];assert '\n' in rows[0]['review_note'];assert rows[0]['review_note'].startswith("'=SUM");checks.append('quoted comma/newline/formula-like note round-trips with spreadsheet protection')
r=json.loads(Path('export-max.json').read_text());rows=list(csv.DictReader(io.StringIO(Path('export-max.csv').read_text())));assert len(rows)==12;assert rows[-1]['review_note']=='last note\nkept';checks.append('maximum 12-card envelope and CSV preserve every record')
Path('artifact-validation.json').write_text(json.dumps({'independentPythonCsvJsonParser':True,'checks':checks},indent=2));print('PASS independently parsed actual downloads')
